"""Capture routing and storage in an isolated local browser; no device camera required."""
import json


def run_mobile_capture_checks(*, cdp, evaluate, check, wait_for, load, add, select, click_selector, shot):
    galaxy = add('Capture trip')
    owner = add('Travel photos', galaxy)
    other = add('Packing list', galaxy)
    wait_for('physics.settled')
    evaluate('physics.pause()')
    select(owner)
    # Suppress native dialogs only; exercise the real buttons, change handlers,
    # validation, repository transaction and IndexedDB storage below.
    evaluate("""window.capturePickers=[];contentInspector.files.click=function(){capturePickers.push({accept:this.getAttribute('accept'),capture:this.getAttribute('capture'),multiple:this.multiple,label:this.getAttribute('aria-label')});};""")
    evaluate(f"toggleContentMenu(addMenu,hierarchySidebar.rows.get({json.dumps(owner)}).querySelector('.tree-add'),{json.dumps(owner)})")
    check(evaluate("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent).join('|')==='Add item|Add existing item|Paste|Add files|Add note|Add bookmark'"), 'desktop Add retains its actions and receives Paste from management')
    evaluate("addMenu.querySelector('[data-add=files]').click()")
    check(evaluate("capturePickers.at(-1).accept===null&&capturePickers.at(-1).capture===null&&capturePickers.at(-1).multiple"), 'desktop Files keeps the ordinary multiple-file picker')
    evaluate("contentInspector.files.dispatchEvent(new Event('cancel'));closeInspector()")

    def mobile(width, height):
        cdp.call('Emulation.setDeviceMetricsOverride', width=width, height=height, deviceScaleFactor=1, mobile=True)
        cdp.call('Emulation.setTouchEmulationEnabled', enabled=True, maxTouchPoints=5)
        wait_for('hierarchySidebar.narrow')
        evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')

    def cancel():
        evaluate("contentInspector.files.dispatchEvent(new Event('cancel'))")

    mobile(390, 844)
    evaluate(f"closeInspector();hierarchySidebar.setCollapsed(true);nodes.get({json.dumps(owner)}).click()")
    check(evaluate(f"panel.hidden&&selectedNode.dataset.entryId==={json.dumps(owner)}&&document.getElementById('mobile-body-actions').getClientRects().length>0"), 'mobile body selection exposes capture/actions without opening Contents')
    check(evaluate("(()=>{const a=document.getElementById('mobile-body-add').getBoundingClientRect(),m=document.getElementById('mobile-body-more').getBoundingClientRect();return a.width>=44&&m.width>=44&&a.right<=m.left;})()"), 'canvas + and actions have separate nonoverlapping 44px targets')
    def tap(selector):
        point = evaluate(f"(()=>{{const r=document.querySelector({json.dumps(selector)}).getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}};}})()")
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[point])
        cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[])

    evaluate(f"focusEntry({json.dumps(owner)},{{closeFocus:true,openInspector:false}})")
    wait_for('camera.frame===null')
    tap(f'.entry-node[data-entry-id="{owner}"]')
    check(evaluate(f'panel.hidden&&selectedNode.dataset.entryId==={json.dumps(owner)}'), 'a real body tap selects its body and leaves Contents closed')
    tap('#mobile-body-add')
    quick_labels = 'Take Photo|Photo Library / Gallery|Quick note|More…'
    full_labels = 'Take Photo|Photo Library / Gallery|Files|Add item|Add existing item|Paste|Note|Bookmark'
    def labels():
        return evaluate("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent).join('|')")

    check(labels() == quick_labels, 'CB View has exactly Take Photo, Gallery, Quick note and More')
    check(evaluate("addMenu.dataset.view==='quick'&&addMenu.querySelectorAll('[role=separator]:not([hidden])').length===0"), 'quick menu has no hidden full-menu actions exposed or group dividers')
    shot('mobile-capture-390-menu')
    preview_destination = evaluate('addMenuTargetId')
    evaluate('closeContentMenus();setInspectorOpen(true)')
    tap('#entry-add-button')
    check(labels() == quick_labels and evaluate('addMenuTargetId') == preview_destination, 'Contents header + opens exactly the preview quick menu for the same body')
    check(evaluate("addMenuTrigger.id==='entry-add-button'&&document.getElementById('entry-add-button').getAttribute('aria-expanded')==='true'"), 'Contents Add uses the shared menu trigger and expanded state')
    shot('mobile-capture-390-contents-menu')
    tap('#add-menu [data-add=more]')
    check(labels() == full_labels and evaluate('addMenuTargetId') == preview_destination, 'Contents More expands the same full Add menu for the same body')
    cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
    cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Escape',code='Escape',windowsVirtualKeyCode=27)
    check(evaluate("addMenu.hidden&&document.activeElement.id==='entry-add-button'&&document.activeElement.getAttribute('aria-expanded')==='false'"), 'Contents menu Escape restores its header + and clears expanded state')
    tap('#entry-add-button'); tap('#entry-add-button')
    check(evaluate('addMenu.hidden'), 'Contents + toggles the shared Add menu closed on a second tap')
    check(evaluate("['files','media','bookmark','location'].every((kind,i)=>document.getElementById('content-add-'+kind).textContent===['Add file','Add media','Paste a link…','Add location…'][i])"), 'section entry points have explicit labels instead of ambiguous bare plus signs')
    shot('mobile-capture-390-contents-header')
    tap('#content-add-files')
    check(evaluate("capturePickers.at(-1).accept===null&&capturePickers.at(-1).capture===null&&capturePickers.at(-1).multiple&&addMenu.hidden&&!panel.hidden"), 'Add file retains its original section-specific picker without opening the body Add menu')
    cancel()
    evaluate('closeInspector()')
    tap('#mobile-body-add')
    before = evaluate("localStorage.getItem('galaxy:user-data')")
    tap('#add-menu [data-add=camera]')
    check(evaluate("capturePickers.at(-1).capture==='environment'&&capturePickers.at(-1).accept==='image/*'&&!capturePickers.at(-1).multiple&&panel.hidden&&addMenu.hidden"), 'Take Photo directly requests a single outward-facing image without a details form')
    cancel()
    check(evaluate("panel.hidden&&contentInspector.fileSelection===null&&document.getElementById('content-file-limit').hidden"), 'camera cancellation clears picker state and leaves Contents closed')
    check(evaluate("localStorage.getItem('galaxy:user-data')") == before, 'cancel does not write metadata')
    click_selector('#mobile-body-add'); click_selector('#add-menu [data-add=gallery]')
    check(evaluate("capturePickers.at(-1).capture===null&&capturePickers.at(-1).accept.includes('.heic')&&capturePickers.at(-1).multiple&&panel.hidden"), 'Gallery allows photos including HEIF and removes camera capture')
    cancel()
    click_selector('#mobile-body-add'); click_selector('#add-menu [data-add=more]')
    check(labels() == full_labels, 'More expands the complete grouped Add menu')
    check(evaluate(f"addMenuTargetId==={json.dumps(owner)}&&hierarchySidebar.collapsed&&selectedNode.dataset.entryId==={json.dumps(owner)}&&addMenuTrigger.id==='mobile-body-add'"), 'More retains destination, selection and trigger without opening the sidebar')
    shot('mobile-capture-390-full-menu')
    click_selector('#add-menu [data-add=capture-files]')
    check(evaluate("capturePickers.at(-1).capture===null&&capturePickers.at(-1).accept===null&&capturePickers.at(-1).multiple"), 'Files resets both camera and gallery filters')
    cancel()
    click_selector('#mobile-body-add')
    check(labels() == quick_labels, 'reopening CB + returns to the quick menu after More')
    click_selector('#add-menu [data-add=quick-note]')
    check(evaluate(f"contentInspector.entryId==={json.dumps(owner)}&&!contentInspector.notesForm.hidden&&addMenu.hidden"), 'Quick note routes to the existing note editor for the same body')
    evaluate("document.getElementById('content-cancel-notes').click();closeInspector()")
    click_selector('#mobile-body-more')
    check(evaluate("!contextMenu.hidden&&contextMenu.getAttribute('aria-label').includes('Travel photos')&&addMenu.hidden"), 'separate canvas actions opens the existing item menu')
    evaluate('closeContextMenu(true)')
    check(evaluate("document.getElementById('mobile-body-more').getAttribute('aria-expanded')==='false'"), 'closing actions clears expanded state')

    for width, height in [(320, 568), (390, 844), (844, 390)]:
        mobile(width, height)
        evaluate('closeInspector();hierarchySidebar.setCollapsed(false)')
        check(evaluate("[...document.querySelectorAll('.hierarchy-row[data-entry-id]')].every(row=>{const a=row.querySelector('.tree-add'),m=row.querySelector('.tree-more'),ar=a.getBoundingClientRect(),mr=m.getBoundingClientRect();return getComputedStyle(a).visibility==='visible'&&getComputedStyle(m).display!=='none'&&ar.width>=44&&mr.width>=44&&ar.right<=mr.left&&mr.right<=innerWidth;})"), f'{width}x{height}: every row has independently visible + and actions')
        evaluate(f"hierarchySidebar.rows.get({json.dumps(owner)}).querySelector('.tree-add').click()")
        check(labels() == full_labels, f'{width}x{height}: Menu View directly opens the complete Add menu')
        check(evaluate("addMenu.dataset.view==='full'&&addMenu.querySelectorAll('[role=separator]:not([hidden])').length===2"), f'{width}x{height}: full menu groups capture, organization and writing')
        check(evaluate("(()=>{const r=addMenu.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight&&r.width<=270;})()"), f'{width}x{height}: full Add menu stays inside viewport')
        check(evaluate("(()=>{const a=getComputedStyle(addMenu),m=getComputedStyle(contextMenu),ab=getComputedStyle(addMenu.querySelector('[data-add=camera]')),mb=getComputedStyle(contextMenu.querySelector('[data-action=edit]'));return ['backgroundColor','borderRadius','padding','boxShadow','borderColor','borderWidth'].every(k=>a[k]===m[k])&&['fontSize','fontFamily','padding','borderRadius','minHeight','color'].every(k=>ab[k]===mb[k]);})()"), f'{width}x{height}: Add surface and rows match the existing actions menu')
        shot(f'mobile-capture-{width}-drawer')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        check(evaluate("addMenu.hidden&&document.activeElement.classList.contains('tree-add')"), f'{width}x{height}: Escape returns to the same +')
        evaluate('hierarchySidebar.setCollapsed(true);setInspectorOpen(true);panel.scrollTop=0')
        check(evaluate("(()=>{const a=document.getElementById('entry-add-button').getBoundingClientRect(),m=moreButton.getBoundingClientRect(),n=panelName.getBoundingClientRect();return a.width>=44&&a.height>=44&&a.left>=n.right&&a.right<=m.left&&m.right<=innerWidth&&n.width>0;})()"), f'{width}x{height}: Contents title, body + and existing actions remain separate and reachable')
        check(evaluate("(()=>{const a=document.getElementById('content-add-files'),r=a.getBoundingClientRect();return a.textContent==='Add file'&&r.width>=44&&r.height>=44&&r.right<=innerWidth;})()"), f'{width}x{height}: explicit Add file stays readable with a touch target')
        tap('#entry-add-button')
        check(labels() == quick_labels and evaluate('addMenuTargetId') == owner, f'{width}x{height}: Contents header retains quick choices and exact body identity')
        check(evaluate("(()=>{const r=addMenu.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight;})()"), f'{width}x{height}: Contents Add menu stays within the viewport')
        shot(f'mobile-capture-{width}-contents-menu')
        evaluate('closeContentMenus();closeInspector()')
    mobile(390, 844)
    evaluate('hierarchySidebar.setCollapsed(true)')
    # Context, rather than trigger identity, selects quick/full mode. Use a row's
    # retained destination distinct from the selected body to exercise More.
    evaluate(f"selectEntry(entries.get({json.dumps(other)}),nodes.get({json.dumps(other)}),{{openInspector:false}});toggleContentMenu(addMenu,hierarchySidebar.rows.get({json.dumps(owner)}).querySelector('.tree-add'),{json.dumps(owner)})")
    check(labels() == quick_labels, 'closed-sidebar context uses quick mode independently of the trigger')
    evaluate("addMenu.querySelector('[data-add=more]').click()")
    check(evaluate(f"addMenuTargetId==={json.dumps(owner)}&&selectedNode.dataset.entryId==={json.dumps(other)}") and labels() == full_labels, 'More preserves an unselected destination instead of substituting the active body')
    evaluate('closeContentMenus()')
    # Create a genuine PNG with the browser, then change selection before delivery.
    evaluate(f"openEntryContentAction({json.dumps(owner)},'gallery');selectEntry(entries.get({json.dumps(other)}),nodes.get({json.dumps(other)}),{{openInspector:false}})")
    evaluate("""(async()=>{const c=document.createElement('canvas');c.width=80;c.height=60;c.getContext('2d').fillRect(0,0,80,60);const blob=await new Promise(r=>c.toBlob(r,'image/png'));window.capturePhoto=new File([blob],'camera-photo.png',{type:'image/png'});const d=new DataTransfer();d.items.add(capturePhoto);contentInspector.files.files=d.files;contentInspector.files.dispatchEvent(new Event('change'));})()""")
    wait_for('contentInspector.jobs.size===0&&contentInspector.content().attachments.length===1')
    check(evaluate(f"!panel.hidden&&contentInspector.entryId==={json.dumps(owner)}&&!(entries.get({json.dumps(other)}).content?.attachments.length)"), 'picker result attaches to its original destination after selection changes')
    check(evaluate("(async()=>{const f=contentInspector.content().attachments[0],r=await attachmentStore.get(f.storageKey);return r.entryId===f.entryId&&r.blob.size===capturePhoto.size&&!!r.thumbnail&&f.width===80&&f.height===60;})()"), 'capture uses existing original-byte and thumbnail storage transaction')
    evaluate("document.querySelector('#content-media .content-media-viewport').click()")
    wait_for('imageViewer.dialog.open&&!imageViewer.image.hidden')
    check(evaluate('imageViewer.image.naturalWidth===80'), 'existing image lightbox still opens captured photos')
    evaluate('imageViewer.dialog.close()')
    evaluate("contentInspector.upload([new File(['blocked'],'unsafe.exe',{type:'image/jpeg'})])")
    wait_for('contentInspector.jobs.size===0')
    check(evaluate("contentInspector.content().attachments.length===1&&contentInspector.status.textContent.includes('Executable')"), 'capture does not bypass executable restrictions; failure leaves existing photo intact')
    # Unsupported native HEIF decode must remain a recoverable original.
    evaluate("window.originalBitmap=createImageBitmap;window.createImageBitmap=()=>Promise.reject(Error('unsupported HEIF'));contentInspector.upload([new File(['original HEIF bytes'],'original.heic',{type:'image/heic'})])")
    wait_for('contentInspector.jobs.size===0&&contentInspector.content().attachments.length===2')
    check(evaluate("(async()=>{const f=contentInspector.content().attachments[1],r=await attachmentStore.get(f.storageKey);return f.filename==='original.heic'&&await r.blob.text()==='original HEIF bytes'&&!r.thumbnail&&galaxyModel.filePolicy.isMedia(f);})()"), 'unsupported HEIF retains original bytes as Media without a destructive conversion')
    evaluate('window.createImageBitmap=originalBitmap')
    evaluate("document.querySelectorAll('#content-media .content-media-viewport')[1].click()")
    wait_for("imageViewer.dialog.open&&imageViewer.status.textContent.includes('Preview unavailable')")
    check(evaluate('!imageViewer.saveCopy.hidden'), 'unsupported HEIF viewer retains Save a copy fallback')
    check(evaluate("(async()=>await (await fetch(imageViewer.saveCopy.href)).text()==='original HEIF bytes')()"), 'unsupported HEIF Save a copy points to the original bytes')
    shot('mobile-capture-heif-fallback')
    evaluate("imageViewer.dialog.close();(async()=>{const f=contentInspector.content().attachments[1],r=await attachmentStore.get(f.storageKey);await attachmentStore.save({...r,thumbnail:capturePhoto});})()")
    evaluate("document.querySelectorAll('#content-media .content-media-viewport')[1].click()")
    wait_for('imageViewer.dialog.open&&!imageViewer.image.hidden')
    check(evaluate("(async()=>imageViewer.image.naturalWidth===80&&imageViewer.url!==imageViewer.originalUrl&&await(await fetch(imageViewer.infoCopy.href)).text()==='original HEIF bytes')()"), 'friendly HEIF preview displays while Info download retains the original')
    evaluate('imageViewer.dialog.close();closeInspector()')
    wait_for('!imageViewer.dialog.open&&imageViewer.originalUrl===null&&imageViewer.url===null')
    check(evaluate('imageViewer.originalUrl===null&&imageViewer.url===null'), 'closing preview releases original and preview object URLs')
    click_selector('#mobile-body-contents')
    check(evaluate('!panel.hidden'), 'Contents remains explicitly accessible after mobile navigation')
    check(not cdp.errors, f'no capture browser exceptions: {cdp.errors}')
